{'code': 'from qgis.PyQt.QtWidgets import QAction, QToolButton, QDockWidget, QMenu
mw = iface.mainWindow()
res = []
target = None
for a in mw.findChildren(QAction):
    if a.objectName() == 'editInPlaceFeatures':
        target = a
        break
# このアクションをdefaultActionに持つボタンを探す
for btn in mw.findChildren(QToolButton):
    if btn.defaultAction() is target:
        # 親チェーンを辿る
        chain = []
        p = btn.parent()
        while p is not None:
            chain.append(f"{p.metaObject().className()}({p.objectName()})")
            p = p.parent()
            if len(chain) > 8:
                break
        res.append({'button_in': ' <- '.join(chain), 'btn_visible': btn.isVisible()})
# メニュー内にあるか
for m in mw.findChildren(QMenu):
    if target in m.actions():
        res.append({'in_menu': m.title()})
result = res'}

